  .br-edit-grid { grid-template-columns: minmax(0, 1fr); }
  .br-edit-condition,
  .br-edit-effect { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; padding: 10px; }
  .br-edit-condition > :last-child,
  .br-edit-effect > :last-child { justify-self: stretch; }
  .br-edit-rule { padding: 10px; }
  .br-edit-rule > legend { padding-inline: 5px; }
}

@media (max-width: 400px) {
  .br-context { gap: 9px; padding: 10px; }
  .br-condition-grid { grid-template-columns: minmax(0, 1fr); }
  .br-toolbar { gap: 7px; }
  .br-toolbar .br-button { flex: 1 1 auto; }
  .br-source-header h3 { flex-basis: 100%; }
  .br-source-header > div:first-child { flex-basis: 100%; }
  .br-tabs button { flex-basis: calc(50% - 4px); }
}

@media (prefers-reduced-motion: reduce) {
