}

.br-source-jump { display: inline; padding: 0; border: 0; background: transparent; color: inherit; font: inherit; font-weight: inherit; text-align: left; cursor: pointer; }
.br-source-jump:hover { color: #245ca3; text-decoration: underline; text-underline-offset: 3px; }
.br-located-source { scroll-margin-block: 76px 24px; }
@media (prefers-reduced-motion: reduce) {
  .br-located-source, .br-located-source > td { animation: none; background-color: #fff0a8; box-shadow: inset 4px 0 #e69623; }
}

.br-contribution-details > summary { width: fit-content; color: #60758f; cursor: pointer; }
.br-contribution-details > p { margin: 6px 0; }

/* Audit marks belong to the original character entries, independently of effect enablement. */
.br-source-audit { width: 17px; height: 17px; margin: 0 8px 0 0; vertical-align: middle; accent-color: #245ca3; cursor: pointer; }
.br-source-audit[hidden] { display: none !important; }
#bonusCalculator[data-rule-calculator] .bonus-calculator-header { gap: 10px; }
#bonusCalculator[data-rule-calculator] .bonus-calculator-header > strong { flex: 1; }
#bonusCalculator[data-rule-calculator] .br-clear-audit { flex: 0 0 auto; width: auto; padding: 0 10px; border-radius: 5px; font-size: 14px; line-height: 1.4; }

