const characterId=document.body.dataset.characterId;
let ready=false;
let lastStored='';
function publish() {
  const calc=window.LC_EFFECT_CALCULATOR;
  const base=(calc?.getIndependentReport?.()||calc?.getReport())||characterReportFromDocument(document);
