.equipment-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.equipment-card { border: 1px solid var(--line); }
.equipment-card h4 { margin: 0; padding: 11px 12px; color: var(--navy); background: #edf3fa; border-bottom: 1px solid var(--line); }
.equipment-card dl { display: grid; grid-template-columns: 78px 1fr; margin: 0; }
.equipment-card dt, .equipment-card dd { margin: 0; padding: 10px 11px; border-bottom: 1px solid #dbe2ec; }
