.equipment-card dd:last-child, .equipment-card dt:nth-last-child(2) { border-bottom: 0; }
.source-note { margin: 26px 0 0; padding-top: 14px; border-top: 1px solid #d5deea; color: var(--muted); font-size: .78rem; line-height: 1.7; }
.source-note a { color: #315f9d; }

.calculator-overlay { display: none !important; }
