.saved-build-skills { padding-bottom: 62px; }
.saved-build-skill { min-height: 58px; display: grid; grid-template-columns: minmax(0, 1fr) 64px 96px 30px; align-items: center; column-gap: 12px; row-gap: 8px; padding: 9px 13px; border-bottom: 1px solid #ccd7e6; background: #fff; }
.saved-build-skill-name { min-width: 0; padding: 0; border: 0; color: inherit; background: transparent; font: inherit; font-weight: 700; text-align: left; overflow-wrap: anywhere; cursor: pointer; }
