.saved-build-skill-rating { width: 100%; min-height: 30px; padding: 4px 6px; border: 1px solid #b7c6da; border-radius: 5px; color: #7147a6; background: #f9f7ff; font: inherit; font-size: .76rem; font-weight: 700; text-align: center; cursor: pointer; }
