.saved-build-skill-effect { grid-column: 1 / -1; margin: 0; padding: 9px 10px; color: #536177; background: #f1f6fc; border-left: 3px solid #6f9bd2; font-size: .8rem; line-height: 1.55; }
.saved-build-empty { padding: 34px 16px; color: #66748b; text-align: center; line-height: 1.65; }
.saved-build-bonus-summary { padding: 7px 12px 72px; background: #fff; }
.saved-build-bonus-row { width: 100%; min-height: 44px; display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 8px 4px; border: 0; border-bottom: 1px solid #d9e1ec; color: #26374f; background: transparent; text-align: left; font: inherit; cursor: pointer; }
.saved-build-bonus-row:hover,
.saved-build-bonus-row.is-expanded { background: #edf4fb; }
