.saved-build-bonus-note { margin: 10px 3px 1px; color: #66748b; font-size: .75rem; line-height: 1.45; }
.saved-build-total { position: sticky; bottom: 0; z-index: 2; display: flex; justify-content: space-between; align-items: center; padding: 13px 15px; color: #172033; background: #f7faff; border-top: 2px solid #9fb4d0; font-size: 1rem; }
