.saved-build-total button:disabled { color: #9aa6b5; background: #eef2f7; cursor: default; }
.saved-build-total strong { color: #203864; font-size: 1.35rem; font-variant-numeric: tabular-nums; }
.mobile-calculator-tabs { display: none; }
.calculator-tools { display: flex; align-items: center; justify-content: flex-end; gap: 10px; padding: 10px 12px; color: #57677f; background: #edf4fb; border-bottom: 1px solid #cad6e6; }
.calculator-tools p { flex: 1; margin: 0; font-size: .8rem; line-height: 1.55; }
.calculator-tools button { flex: 0 0 auto; padding: 6px 9px; border: 1px solid #9eb1ca; color: #315b91; background: #fff; font: inherit; font-size: .76rem; cursor: pointer; }
.calculator-tools button:hover { background: #dcecff; }
.bonus-summary { padding-bottom: 20px; }
.bonus-empty { padding: 30px 16px; color: var(--muted); text-align: center; }
.bonus-row { border-bottom: 1px solid #ccd7e6; background: #fff; }
.bonus-row-head { display: grid; grid-template-columns: 1fr 38px; align-items: stretch; }
.bonus-row-button {
  width: 100%;
  min-height: 52px;
  display: grid;
  grid-template-columns: 1fr auto 22px;
  align-items: center;
  gap: 10px;
  padding: 10px 13px;
  border: 0;
  color: var(--ink);
  background: transparent;
  text-align: left;
  font: inherit;
  cursor: pointer;
}
