 c.op==='eq'&&c.value===true||c.op==='in'&&Array.isArray(c.value)&&c.value.length===1&&c.value[0]===true||
 c.op==='notIn'&&Array.isArray(c.value)&&c.value.includes(false)&&!c.value.includes(true)));
